-- 0008_results_and_newsletter.sql
--
-- Run after 0007. Two things the public site needs before it goes live.
--
-- ── Results ──
-- /results was publishing invented data. Two sources of it:
--
--   * five hardcoded finishers ("David Kiprono", "Sarah Jenkins", ...) were
--     concatenated onto the real list in Results.jsx, so the page has always
--     shown five people who do not exist;
--   * every genuine registration was given a `mock_finish_time` at sign-up,
--     generated by rounding a product of two random numbers into a plausible
--     looking duration. A runner who had merely registered could look up their
--     bib and find a finishing time and a rank waiting for them.
--
-- Published race results are a factual record. Runners use them for club
-- rankings and qualifying times. This adds a real finish_time column, a
-- per-event switch that keeps results hidden until they are ready, and a
-- read-only function that exposes nothing but what belongs on a results board.
--
-- ── Newsletter ──
-- The footer form flipped a bit of React state to "Subscribed!" and discarded
-- the address. Anyone who signed up was told it worked and heard nothing again.
--
-- Safe to re-run.

-- ── 1. Results are hidden until an organiser publishes them ─────────────────
alter table public.events
  add column if not exists results_published boolean not null default false,
  add column if not exists results_published_at timestamptz;

comment on column public.events.results_published is
  'False keeps /results empty for this event. Flip it only once timings are final -- published results are treated as a factual record.';

-- ── 2. Real timings ─────────────────────────────────────────────────────────
alter table public.registrations
  add column if not exists finish_time   interval,
  add column if not exists finish_status text not null default 'REGISTERED';

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'registrations_finish_status_check'
  ) then
    alter table public.registrations
      add constraint registrations_finish_status_check
      check (finish_status in ('REGISTERED', 'STARTED', 'FINISHED', 'DNF', 'DNS', 'DQ'));
  end if;
end $$;

comment on column public.registrations.finish_time is
  'Chip time. NULL until the runner finishes. Only rows with finish_status FINISHED and a non-null time are ranked.';
comment on column public.registrations.finish_status is
  'REGISTERED (default) | STARTED | FINISHED | DNF (did not finish) | DNS (did not start) | DQ (disqualified).';

-- ── 3. Retire the fabricated times ──────────────────────────────────────────
-- Kept as a column rather than dropped, so the change is reversible and nobody
-- loses data they were unexpectedly relying on -- but renamed so it can never
-- again be mistaken for a result, and no longer written by anything.
do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'registrations'
      and column_name = 'mock_finish_time'
  ) and not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'registrations'
      and column_name = 'deprecated_mock_finish_time'
  ) then
    alter table public.registrations
      rename column mock_finish_time to deprecated_mock_finish_time;

    comment on column public.registrations.deprecated_mock_finish_time is
      'Randomly generated placeholder from the pre-launch demo build. Never a real timing. Nothing reads or writes it; drop the column once you are satisfied nothing depends on it.';

    raise notice 'registrations.mock_finish_time renamed to deprecated_mock_finish_time -- it held randomly generated times, not real results.';
  end if;
end $$;

-- ── 4. The public results board ─────────────────────────────────────────────
-- Returns an empty set unless the event has results_published set, and exposes
-- only what a results board shows. Notably absent: email, phone, date of birth,
-- blood group, emergency contact, address.
create or replace function public.get_published_results(p_event_id text)
returns table (
  bib           text,
  runner_name   text,
  category      text,
  finish_time   text,
  finish_status text,
  category_rank integer,
  overall_rank  integer
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with published as (
    select r.*
    from public.registrations r
    join public.events e on e.id = r.event_id
    where r.event_id = p_event_id
      and e.results_published is true
      and r.payment_status not in ('CANCELLED')
      and r.finish_status in ('FINISHED', 'DNF', 'DNS', 'DQ')
  )
  select
    p.bib,
    trim(coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, '')),
    p.category,
    -- HH:MM:SS, so a 4-hour marathon does not render as "04:00:00" in one
    -- place and "4:0:0" in another.
    case when p.finish_time is null then null
         else to_char(p.finish_time, 'HH24:MI:SS') end,
    p.finish_status,
    case when p.finish_status = 'FINISHED' and p.finish_time is not null
         then rank() over (
           partition by p.category
           order by p.finish_time
         )::integer end,
    case when p.finish_status = 'FINISHED' and p.finish_time is not null
         then rank() over (order by p.finish_time)::integer end
  from published p
  order by
    case when p.finish_status = 'FINISHED' and p.finish_time is not null then 0 else 1 end,
    p.finish_time nulls last,
    p.bib;
$$;

revoke all on function public.get_published_results(text) from public;
grant execute on function public.get_published_results(text) to anon, authenticated;

comment on function public.get_published_results(text) is
  'Public results board. Empty until events.results_published is true. Exposes bib, name, category, time and rank only -- never contact, medical or address data.';

-- ── 5. Newsletter sign-ups ──────────────────────────────────────────────────
create table if not exists public.newsletter_subscribers (
  id            uuid primary key default gen_random_uuid(),
  email         text not null,
  source        text,
  is_subscribed boolean not null default true,
  created_at    timestamptz not null default now()
);

create unique index if not exists newsletter_subscribers_email_key
  on public.newsletter_subscribers (lower(email));

comment on table public.newsletter_subscribers is
  'Addresses collected by the footer sign-up form. Insert-only for the public: a visitor can add an address but cannot read the list back.';

-- ENABLE, not FORCE: subscribe_to_newsletter() runs as the table owner.
alter table public.newsletter_subscribers enable row level security;

drop policy if exists newsletter_admin_all on public.newsletter_subscribers;
create policy newsletter_admin_all on public.newsletter_subscribers
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- No anon policy: sign-up goes through the function below, so the table itself
-- can never be listed by someone holding the public key.
create or replace function public.subscribe_to_newsletter(p_email text, p_source text default 'footer')
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_email text := lower(trim(p_email));
begin
  if v_email is null or v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'EMAIL_INVALID' using errcode = 'P0001';
  end if;

  insert into public.newsletter_subscribers (email, source)
  values (v_email, nullif(p_source, ''))
  on conflict (lower(email)) do update
    set is_subscribed = true;

  -- Always the same answer, subscribed or already-subscribed. Distinguishing
  -- them would turn this into a way to test whether an address is on the list.
  return true;
end $$;

revoke all on function public.subscribe_to_newsletter(text, text) from public;
grant execute on function public.subscribe_to_newsletter(text, text) to anon, authenticated;

revoke all on public.newsletter_subscribers from anon;
